  "inlineSchema": "// Wondalis database schema (PostgreSQL).\n//\n// Conventions used throughout:\n// - Money is stored as whole integers in minor units (USD cents, GHS pesewas). Never floats.\n// - USD is the base currency. Each booking locks the USD→GHS rate at booking time.\n// - Things that can be calculated (seats booked, amount paid, payment status) are NOT stored.\n//   They are derived from the rows that cause them, so they can never drift out of sync.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ───────────────────────── Enums ─────────────────────────\n\nenum TripType {\n  GHANA\n  ABROAD\n}\n\nenum TripStatus {\n  DRAFT\n  PUBLISHED\n}\n\nenum TripTag {\n  BEACH\n  HERITAGE\n  FAMILY\n}\n\nenum Role {\n  CUSTOMER\n  STAFF\n  OWNER\n}\n\nenum Currency {\n  USD\n  GHS\n}\n\nenum PaymentMethod {\n  CARD\n  MOBILE_MONEY\n  BANK_TRANSFER\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n}\n\nenum FxMode {\n  LIVE\n  FIXED\n}\n\n// ───────────────────────── Trips ─────────────────────────\n\nmodel Trip {\n  id              String     @id @default(cuid())\n  slug            String     @unique\n  title           String\n  destination     String // e.g. \"Accra · Labadi\"\n  type            TripType\n  tags            TripTag[]\n  overview        String     @default(\"\")\n  highlights      String[]\n  included        String[]\n  coverImage      String\n  gallery         String[]\n  priceUsdCents   Int\n  priceGhsPesewas Int // real cedi price, so Ghana trips are not just USD × rate\n  depositPct      Int        @default(30)\n  status          TripStatus @default(DRAFT)\n  seoTitle        String?\n  seoDescription  String?\n  createdAt       DateTime   @default(now())\n  updatedAt       DateTime   @updatedAt\n\n  itinerary  ItineraryDay[]\n  departures Departure[]\n\n  @@index([status, type])\n}\n\nmodel ItineraryDay {\n  id       String @id @default(cuid())\n  tripId   String\n  trip     Trip   @relation(fields: [tripId], references: [id], onDelete: Cascade)\n  position Int // 1, 2, 3… the order shown on the trip page\n  title    String\n  body     String @default(\"\")\n\n  @@unique([tripId, position])\n}\n\n// A dated run of a trip. The same trip can leave more than once.\nmodel Departure {\n  id         String   @id @default(cuid())\n  tripId     String\n  trip       Trip     @relation(fields: [tripId], references: [id], onDelete: Cascade)\n  startsOn   DateTime @db.Date\n  endsOn     DateTime @db.Date\n  seatsTotal Int\n\n  bookings Booking[]\n\n  @@index([tripId, startsOn])\n}\n\n// ───────────────────────── People ─────────────────────────\n\n// A login. Customers, staff and the owner all sign in through this table.\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  name         String?\n  passwordHash String? // null for Google-only accounts\n  role         Role     @default(CUSTOMER)\n  createdAt    DateTime @default(now())\n\n  customer         Customer?\n  recordedPayments Payment[]\n\n  // Auth.js tables (Account, Session, VerificationToken) are added in the auth step.\n}\n\n// Someone who books. Separate from User because guest checkout is allowed:\n// a customer can exist without ever creating a login.\nmodel Customer {\n  id               String   @id @default(cuid())\n  userId           String?  @unique\n  user             User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  firstName        String\n  lastName         String\n  email            String   @unique\n  whatsapp         String?\n  residenceCountry String // \"Ghana\" means In Ghana; anything else is Diaspora (derived, not stored)\n  createdAt        DateTime @default(now())\n\n  bookings Booking[]\n}\n\n// ───────────────────────── Bookings and money ─────────────────────────\n\nmodel Booking {\n  id          String    @id @default(cuid())\n  refNumber   Int       @unique @default(autoincrement()) // shown as WTT-000123\n  customerId  String\n  customer    Customer  @relation(fields: [customerId], references: [id])\n  departureId String\n  departure   Departure @relation(fields: [departureId], references: [id])\n\n  totalUsdCents Int\n  currency      Currency // what the customer sees and pays in\n  fxRateLocked  Decimal   @db.Decimal(12, 6) // USD→GHS at booking time; never changes afterwards\n  depositPct    Int // the deposit % that applied when they booked\n  cancelledAt   DateTime?\n  createdAt     DateTime  @default(now())\n\n  travellers  Traveller[]\n  instalments Instalment[]\n  payments    Payment[]\n\n  @@index([customerId])\n  @@index([departureId])\n}\n\nmodel Traveller {\n  id          String  @id @default(cuid())\n  bookingId   String\n  booking     Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  firstName   String\n  lastName    String\n  nationality String? // passport nationality\n  isLead      Boolean @default(false)\n}\n\n// What is OWED and when: \"Deposit\", \"Instalment 1\", \"Balance\"…\nmodel Instalment {\n  id             String    @id @default(cuid())\n  bookingId      String\n  booking        Booking   @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  position       Int\n  label          String\n  amountUsdCents Int\n  dueOn          DateTime? @db.Date // null = due immediately\n\n  payments Payment[]\n\n  @@unique([bookingId, position])\n}\n\n// What was actually RECEIVED (or attempted). Append-only ledger: rows are never edited\n// to change an amount; a mistake is fixed by a new row, so there is always an audit trail.\nmodel Payment {\n  id             String        @id @default(cuid())\n  bookingId      String\n  booking        Booking       @relation(fields: [bookingId], references: [id])\n  instalmentId   String?\n  instalment     Instalment?   @relation(fields: [instalmentId], references: [id])\n  amountUsdCents Int // value in USD, so totals add up across currencies\n  currency       Currency // what the customer actually paid in\n  amountMinor    Int // amount in that currency's minor unit (cents or pesewas)\n  fxRate         Decimal       @db.Decimal(12, 6)\n  method         PaymentMethod\n  status         PaymentStatus @default(PENDING)\n  providerRef    String?       @unique // Paystack reference; unique makes webhook handling idempotent\n  note           String?\n  recordedById   String? // set when staff record a manual (bank/cash) payment\n  recordedBy     User?         @relation(fields: [recordedById], references: [id])\n  paidAt         DateTime?\n  createdAt      DateTime      @default(now())\n\n  @@index([bookingId])\n  @@index([status, createdAt])\n}\n\n// ───────────────────────── Settings ─────────────────────────\n\n// Exactly one row (id = 1). Edited in Admin > Settings.\nmodel Setting {\n  id                 Int             @id @default(1)\n  baseCurrency       Currency        @default(USD)\n  fxMode             FxMode          @default(LIVE)\n  fixedRate          Decimal         @default(15) @db.Decimal(12, 6)\n  liveRate           Decimal?        @db.Decimal(12, 6) // cached by the daily job\n  liveRateUpdatedAt  DateTime?\n  displayCurrencies  String[] // extra display-only currencies, e.g. GBP, EUR, CAD\n  enabledMethods     PaymentMethod[]\n  defaultDepositPct  Int             @default(30)\n  balanceDueDays     Int             @default(14) // days before departure\n  cancellationPolicy String          @default(\"\")\n  updatedAt          DateTime        @updatedAt\n}\n",
